#define MUTEX_TRYLOCK(m) (pthread_mutex_trylock(m) == 0)
#define MUTEX_UNLOCK(m)  pthread_mutex_unlock(m)
#define MUTEX_DESTROY(m) pthread_mutex_destroy(m)

